"""
archival_binding_spec module
Provides parse_bindings for parsing section.key=value configuration lines,
and flatten_bindings for serialising the nested dictionary back to lines.
"""


def _is_ignorable(line: str) -> bool:
    """Return True if the line should be skipped (empty or comment)."""
    return not line or line.startswith('#')


def _split_lhs(lhs: str, lineno: int, raw_line: str) -> tuple[str, str]:
    """Split 'section.key' into (section, key), raising ValueError if malformed."""
    if '.' not in lhs:
        raise ValueError(
            f"Line {lineno}: malformed line (missing '.' in section.key): {raw_line!r}"
        )
    section, key = lhs.split('.', 1)
    section = section.strip()
    key = key.strip()
    if not section:
        raise ValueError(
            f"Line {lineno}: empty section name in line: {raw_line!r}"
        )
    if not key:
        raise ValueError(
            f"Line {lineno}: empty key name in line: {raw_line!r}"
        )
    return section, key


def _parse_line(line: str, lineno: int, raw_line: str) -> tuple[str, str, str]:
    """Parse a single configuration line into (section, key, value)."""
    if '=' not in line:
        raise ValueError(
            f"Line {lineno}: malformed line (missing '='): {raw_line!r}"
        )
    lhs, value = line.split('=', 1)
    lhs = lhs.strip()
    value = value.strip()
    section, key = _split_lhs(lhs, lineno, raw_line)
    return section, key, value


def parse_bindings(lines: list[str]) -> dict[str, dict[str, str]]:
    """
    Parse a list of configuration lines into a nested dictionary.

    Each non-empty, non-comment line must be in the format "section.key=value".
    Comments start with '#'. Whitespace around section, key, and value is stripped.

    Args:
        lines: List of strings to parse.

    Returns:
        An insertion-ordered nested dictionary mapping section names to
        dictionaries of key/value pairs.

    Raises:
        TypeError: If lines is not a list, or any element is not a string.
        ValueError: For malformed lines, empty section names, or empty keys.
    """
    if not isinstance(lines, list):
        raise TypeError(
            f"parse_bindings expects a list, got {type(lines).__name__!r}"
        )
    for idx, item in enumerate(lines):
        if not isinstance(item, str):
            raise TypeError(
                f"parse_bindings expects a list of strings; "
                f"element at index {idx} is {type(item).__name__!r}"
            )

    result: dict[str, dict[str, str]] = {}

    for lineno, raw_line in enumerate(lines, start=1):
        line = raw_line.strip()
        if _is_ignorable(line):
            continue
        section, key, value = _parse_line(line, lineno, raw_line)
        if section not in result:
            result[section] = {}
        result[section][key] = value

    return result


def flatten_bindings(bindings: dict[str, dict[str, str]]) -> list[str]:
    """
    Serialise a nested bindings dictionary back to a list of strings.

    Args:
        bindings: A nested dictionary mapping section names to key/value pairs,
                  as returned by parse_bindings.

    Returns:
        A list of strings in "section.key=value" format, in dictionary
        iteration order (sections first, then keys within each section).

    Raises:
        TypeError: If bindings is not a dict, or if any section value is not a
                   dict, or if any section name, key, or value is not a string.
        ValueError: If any section name or key is empty.
    """
    if not isinstance(bindings, dict):
        raise TypeError(
            f"flatten_bindings expects a dict, got {type(bindings).__name__!r}"
        )

    result: list[str] = []
    for section, pairs in bindings.items():
        if not isinstance(section, str):
            raise TypeError(
                f"flatten_bindings expects string section names; "
                f"got {type(section).__name__!r}"
            )
        if not section.strip():
            raise ValueError(
                f"flatten_bindings: section name must not be empty or blank"
            )
        if not isinstance(pairs, dict):
            raise TypeError(
                f"flatten_bindings expects dict values for each section; "
                f"section {section!r} has {type(pairs).__name__!r}"
            )
        for key, value in pairs.items():
            if not isinstance(key, str):
                raise TypeError(
                    f"flatten_bindings expects string keys in section {section!r}; "
                    f"got {type(key).__name__!r}"
                )
            if not key.strip():
                raise ValueError(
                    f"flatten_bindings: key must not be empty or blank "
                    f"in section {section!r}"
                )
            if not isinstance(value, str):
                raise TypeError(
                    f"flatten_bindings expects string values in section {section!r}; "
                    f"key {key!r} has value of type {type(value).__name__!r}"
                )
            result.append(f"{section}.{key}={value}")
    return result

